create or replace function public.cpcm_admin_commission_staff() returns table(email text,full_name text,role text,is_active boolean,commission_rate numeric) language plpgsql security invoker set search_path=public as $$ begin if lower(coalesce(auth.jwt()->>'email',''))<>'afinch2678@gmail.com' then raise exception 'Admin only'; end if; return query select u.email,u.full_name,u.role,u.is_active,u.commission_rate from public.app_users u where lower(coalesce(u.role,'')) in ('admin','employee') and coalesce(u.is_active,true)=true order by lower(u.email); end $$;
create or replace function public.cpcm_my_commission_summary() returns jsonb language sql stable security invoker set search_path=public as $$ with me as(select lower(coalesce(auth.jwt()->>'email','')) email),e as(select * from public.employee_commission_earnings where lower(employee_email)=(select email from me) and status='Earned'),rate as(select commission_rate from public.app_users where lower(email)=(select email from me) limit 1) select jsonb_build_object('commission_rate',coalesce((select commission_rate from rate),0),'today',coalesce((select sum(earned_amount) from e where approved_at>=date_trunc('day',now())),0),'week',coalesce((select sum(earned_amount) from e where approved_at>=date_trunc('week',now())),0),'month',coalesce((select sum(earned_amount) from e where approved_at>=date_trunc('month',now())),0),'year',coalesce((select sum(earned_amount) from e where approved_at>=date_trunc('year',now())),0),'gross_month',coalesce((select sum(gross_amount) from e where approved_at>=date_trunc('month',now())),0),'deal_count_month',(select count(*) from e where approved_at>=date_trunc('month',now())),'recent',coalesce((select jsonb_agg(jsonb_build_object('approved_at',approved_at,'gross_amount',gross_amount,'commission_rate',commission_rate,'earned_amount',earned_amount,'ledger_id',ledger_id) order by approved_at desc) from(select * from e order by approved_at desc limit 100)q),'[]'::jsonb)); $$;
revoke execute on function public.cpcm_admin_commission_staff() from public,anon; revoke execute on function public.cpcm_my_commission_summary() from public,anon; grant execute on function public.cpcm_admin_commission_staff() to authenticated; grant execute on function public.cpcm_my_commission_summary() to authenticated;
